M('gas_pore',P('非飽和土體 V=500 m³；氣相孔隙率 na=0.20；抽氣 Q=50 m³/h','Unsaturated bulk volume V=500 m³; air-filled porosity na=0.20; extraction Q=50 m³/h'),'t=V*na/Q','500*0.20/50','h',P('只將 na 改成 0.10','Change only air-filled porosity na to 0.10'),'500*0.10/50',P('氣相孔隙體積除抽氣量是名目換氣尺度；含水增加同時會改變氣相連通性與滲透性。','Air-filled pore volume divided by extraction flow gives a nominal exchange scale; rising moisture also changes connectivity and gas permeability.'),P('固定流量、均勻氣相，忽略壓縮性；不以較短名目時間推定較好整治。','Fixed flow and uniform gas phase, neglecting compressibility; a shorter nominal time does not establish better remediation.'),P('量土壤含水、各深度真空與氣體濃度，尋找被飽和水或低滲透層隔離區。','Measure moisture, vacuum and gas concentrations by depth to locate zones isolated by water or low-permeability strata.'),P('水分上升可能令可抽氣孔隙變小卻加劇旁通。','Rising moisture can reduce gas-filled pore volume while increasing bypass.'),P('氣相孔隙體積減半就保證整治時間減半。','Halving air-filled pore volume guarantees halving cleanup time.'))
M('sve_mass',P('抽氣 Q=80 m³/h；污染物 C=25 mg/m³；同一乾濕與溫壓基準','Extraction Q=80 m³/h; pollutant C=25 mg/m³ on matching moisture, temperature and pressure bases'),'m=Q*C/1000','80*25/1000','g/h',P('只將 Q 改成 120 m³/h','Change only Q to 120 m³/h'),'120*25/1000',P('抽除質量率等於氣量乘濃度；稀釋可降低濃度而沒有提高污染物移除。','Removal mass rate equals gas flow times concentration; dilution can lower concentration without increasing removal.'),P('準穩態且基準一致，不含管路冷凝或吸附損失。','Quasi-steady conditions and consistent bases, excluding line condensation and sorption losses.'),P('同步記錄流量及分析濃度，積分質量率並核對處理單元前後負荷。','Record flow and concentration simultaneously, integrate mass rate and reconcile loads across off-gas treatment.'),P('只以出口濃度降低判斷進度，可能把吸入清潔空氣視為整治。','Concentration decline alone may mistake clean-air intrusion for remediation.'),P('提高抽氣量總會按相同比例提高實際污染物移除率。','Increasing extraction always increases actual pollutant removal in direct proportion.'))
M('capture_width',P('抽水 Q=100 m³/d；K=10 m/d；含水層厚 b=10 m；遠場梯度 i=0.01','Pumping Q=100 m³/d; K=10 m/d; aquifer thickness b=10 m; far-field gradient i=0.01'),'W=Q/(K*b*i)','100/(10*10*0.01)','m',P('只將 i 改成 0.02','Change only gradient i to 0.02'),'100/(10*10*0.02)',P('均勻遠場的截流寬度由抽水量與天然通量平衡估計，降深範圍與污染捕獲範圍並不相同。','Far-field capture width follows pumping balanced against natural flux; a drawdown zone is not the same as a contamination capture zone.'),P('理想穩態、均質等向性、完全貫穿單井與均勻流；僅概念尺度，非井位設計。','Ideal steady homogeneous isotropic aquifer, fully penetrating single well and uniform flow; a conceptual scale, not well-placement design.'),P('用上、下游和側向觀測井水頭、化學趨勢與流線模型交叉驗證。','Cross-check upgradient, downgradient and lateral heads, chemistry and flow-path models.'),P('補注邊界、部分貫穿或異質層可使理想捕獲寬度失準。','Recharge boundaries, partial penetration and heterogeneity can invalidate ideal capture width.'),P('井旁水位下降就證明整個污染羽流已受控制。','Water-level decline beside a well proves the entire plume is contained.'))
M('retardation',P('乾土體積密度 ρb=1.6 kg/L；Kd=0.5 L/kg；孔隙率 n=0.30','Dry bulk density ρb=1.6 kg/L; Kd=0.5 L/kg; porosity n=0.30'),'R=1+rho_b*Kd/n','1+1.6*0.5/0.30','dimensionless',P('只將 Kd 改成 1.0 L/kg','Change only Kd to 1.0 L/kg'),'1+1.6*1/0.30',P('線性平衡吸附使溶質平均遷移慢於水；吸附不是污染物破壞。','Linear equilibrium sorption slows mean solute travel relative to water; sorption is not contaminant destruction.'),P('線性、可逆、即時平衡吸附及固定密度孔隙率；不適用強非線性或非平衡拖尾。','Linear reversible instantaneous equilibrium sorption with fixed density and porosity; not strongly nonlinear or nonequilibrium tailing.'),P('用批次與柱試驗檢查 Kd 和濃度依賴性，將吸附物與溶解物總量守恆。','Check Kd and concentration dependence in batch and column tests and balance sorbed plus dissolved mass.'),P('把高遲滯因子解讀為已除污會漏掉未來脫附。','Interpreting high retardation as cleanup overlooks later desorption.'),P('被土壤吸附的污染物已從系統永久消失。','Sorbed contamination has permanently vanished from the system.'))
M('daughter',P('母物轉化 n=10 mol；假設中間物化學計量 y=1 mol/mol；再降解 d=6 mol','Parent transformed n=10 mol; assumed intermediate yield y=1 mol/mol; subsequent degradation d=6 mol'),'intermediate=n*y-d','10*1-6','mol',P('只將後續降解 d 改成 3 mol','Change only subsequent degradation d to 3 mol'),'10*1-3',P('串聯反應中間產物的累積是上游生成減下游消耗；只測母物不能判斷完整反應。','Intermediate accumulation in sequential reactions equals upstream formation minus downstream consumption; parent-only analysis cannot establish completion.'),P('抽象單一路徑與已知化學計量，不指定實際污染物的毒性或現場處方。','An abstract single pathway with known stoichiometry; no real-compound toxicity or field prescription is implied.'),P('以莫耳量核對母物、中間物與終產物，附回收率和未量測支路。','Reconcile parent, intermediates and products on a molar basis, including recovery and unmeasured branches.'),P('下游反應受限會在母物已下降時累積中間產物。','A downstream bottleneck accumulates intermediates even while the parent declines.'),P('母物移除百分比必然等於完整降解百分比。','Parent-removal percentage always equals complete-degradation percentage.'))
M('duplicate',P('平行樣 C1=18 mg/kg；C2=22 mg/kg','Duplicate C1=18 mg/kg; C2=22 mg/kg'),'RPD=abs(C1-C2)/((C1+C2)/2)*100','(22-18)/((18+22)/2)*100','%',P('只將 C2 改成 26 mg/kg','Change only C2 to 26 mg/kg'),'(26-18)/((18+26)/2)*100',P('平行樣相對百分差衡量重複性，不能單獨揭露共同系統偏差或整個場址異質性。','Relative percent difference measures duplicate precision but cannot alone reveal shared systematic bias or site-wide heterogeneity.'),P('同基準且高於定量能力的正值；近零時比例不穩，無預設法定合格門檻。','Positive values on the same basis above quantification capability; ratios become unstable near zero, with no assumed legal acceptance threshold.'),P('搭配空白、加標回收和採樣位置檢查差異來自分析或現場不均。','Combine blanks, spikes and sample locations to separate analytical variation from field heterogeneity.'),P('兩樣同受污染或同一校正偏差時，RPD 仍可很低。','Two equally contaminated or equally miscalibrated samples can have a low RPD.'),P('兩個平行樣完全相同就證明結果一定準確。','Identical duplicates prove the result is accurate.'))
M('exposure_mass',P('土中 C=10 mg/kg；假想土壤接觸攝入量 I=50 mg/day','Soil C=10 mg/kg; hypothetical soil ingestion contact I=50 mg/day'),'intake=C*I/1e6','10*50/1e6','mg/day',P('只將 I 改成 100 mg/day','Change only I to 100 mg/day'),'10*100/1e6',P('介質濃度乘接觸量才形成暴露質量；受體行為與接觸路徑決定分析邊界。','Media concentration multiplied by contact quantity gives exposure mass; receptor behaviour and pathway define the boundary.'),P('純單位換算的假想接觸例，未含生體可用率、體重或毒性；非個人健康評估。','A hypothetical unit-conversion example without bioavailability, body mass or toxicity; not an individual health assessment.'),P('先畫出完整接觸路徑，再記錄接觸假設、活動時間與其依據，避免直接以濃度稱風險。','Map a complete pathway before documenting contact assumptions, duration and evidence; do not call concentration alone risk.'),P('漏掉 mg 土壤轉 kg 的因子會產生百萬倍誤差。','Omitting the mg-to-kg soil conversion produces a million-fold error.'),P('污染濃度相同就保證所有使用者的暴露量相同。','Equal contamination concentration guarantees equal exposure for all users.'))

C('b491',P('用真空、氣相通量與反彈證據判讀非飽和土壤氣相抽除','Interpret unsaturated-zone vapor extraction through vacuum, gas mass flux and rebound'),'environment-remediation',['remedy','remedyguidance','sw846'],[
U(P('污染概念模型與非飽和帶','Conceptual site model and vadose zone'),P('先畫水位、透氣層、低滲透夾層與揮發源；氣相抽除依賴可連通的氣體孔隙，不能把飽和水體當成同一介質。','Map the water table, permeable layers, low-permeability lenses and volatile source; extraction relies on connected gas pores rather than treating saturated water identically.'),'gas_pore'),
U(P('分層試抽與氣量配置','Layered pilot extraction and flow allocation'),P('逐井比較氣流和真空回應，把快速吸入地表空氣的井與穿過污染區的井區分。','Compare well-specific flow and vacuum, separating rapid surface-air intrusion from paths through contamination.'),'sve_mass'),
U(P('含水率與氣相連通','Moisture and gas connectivity'),P('在剖面上提高含水率，觀察氣相體積減少與可用路徑被截斷的不同影響。','Increase moisture in the section and distinguish loss of gas volume from interruption of connected pathways.'),'gas_pore'),
U(P('真空抽風機與能耗','Vacuum blower and energy demand'),P('把井頭真空、管路阻力及處理設備壓降分開，使用工作曲線判讀氣量；高真空不必然有效覆蓋污染源。','Separate well vacuum, pipe resistance and treatment pressure drop; use the working curve because strong vacuum need not cover the source.'),'blower'),
U(P('質量移除與稀釋判別','Mass removal versus dilution'),P('配對同時刻流量與濃度並積分，不以濃度單獨下降宣布整治成功。','Pair concurrent flow and concentration and integrate removal rather than declaring success from concentration decline alone.'),'sve_mass'),
U(P('脫附控制與長期拖尾','Desorption control and tailing'),P('把快速抽出的氣相污染與固相緩慢釋放分開；遲滯模型是理解庫存的水土類比，不能直接當氣相分配公式。','Separate rapidly extracted gas contamination from slow solid-phase release; the water-soil retardation model illustrates inventory and is not a gas-partition formula.'),'retardation'),
U(P('尾氣處理介質突破','Off-gas media breakthrough'),P('在數位流程加入吸附處理與前後端採樣，以介質突破和排出負荷追蹤轉移污染的去向。','Add adsorption and upstream/downstream sampling to the digital flow and follow breakthrough and discharged load to track transferred contamination.'),'capacity'),
U(P('停抽與重啟反彈','Shutdown and restart rebound'),P('比較不同停機長度後的重啟曲線；本單元以水相濃度比作無因次示例，氣相資料也必須保持同一量測基準。','Compare restart curves after different idle periods; the dimensionless example uses aqueous units and gas data likewise require matching measurement bases.'),'rebound'),
U(P('觀測網與證據缺口','Monitoring network and evidence gaps'),P('在源區、邊界和低滲透層配置教學採樣格，標出抽氣井附近以外的未驗證區域。','Place teaching sample cells at the source, boundary and low-permeability zones and mark unverified areas away from extraction wells.'),'sampling'),
U(P('階段交接與停止條件','Phase handoff and stopping evidence'),P('整理捕獲、移除質量、反彈和資料有效性；設備在線率只用於交代試驗可靠性，不是清理完成指標。','Combine capture, removed mass, rebound and data validity; equipment availability documents trial reliability rather than cleanup completion.'),'availability')])

C('b492',P('結合含水層捕獲、地上處理與污染反彈評估抽出處理','Evaluate pump-and-treat through aquifer capture, above-ground treatment and rebound'),'environment-remediation',['remedy','remedyguidance','sw846'],[
U(P('地層、水頭與污染羽流','Stratigraphy, heads and contaminant plume'),P('以同一高程基準連結觀測井，先定地下水流向，再區分溶解污染與持續污染源。','Connect monitoring wells to one elevation datum, determine flow direction and distinguish dissolved contamination from continuing sources.'),'gradient'),
U(P('地下水孔隙流速','Groundwater pore velocity'),P('將水力傳導係數、梯度與有效孔隙率逐項測定，避免把地層孔隙率直接等同可移動孔隙率。','Determine conductivity, gradient and effective porosity separately rather than equating total with mobile porosity.'),'advection'),
U(P('抽水井捕獲尺度','Extraction-well capture scale'),P('用理想截流寬度當概念起點，將污染羽流邊界疊圖，再檢查地層與補注是否破壞假設。','Start with ideal capture width, overlay plume boundaries and check whether stratigraphy or recharge invalidates assumptions.'),'capture_width'),
U(P('抽水揚程與地上管線','Pumping head and surface pipework'),P('把水位降深、地面高差及處理設備損失合併為總揚程，追蹤電耗與抽水量。','Combine drawdown, elevation and treatment losses into total head and track energy alongside extracted volume.'),'pump'),
U(P('水量與污染負荷配對','Pairing water flow with contaminant load'),P('用實驗室濃度對齊流量時間窗，地上處理的負荷由質量率決定而非僅看水量。','Align laboratory concentrations with flow intervals; surface-treatment duty depends on mass rate rather than volume alone.'),'massflow'),
U(P('處理介質與突破預測','Treatment media and breakthrough'),P('依污染型態選擇教學吸附流程，計算名目容量並以實際突破曲線校驗。','Select a teaching adsorption flow appropriate to the contaminant form and check nominal capacity against breakthrough.'),'capacity'),
U(P('孔隙體積與清理拖尾','Pore volumes and cleanup tailing'),P('計算抽水孔隙體積數後，仍檢查低滲透區擴散與吸附庫存，不以換水次數代替清理證據。','After calculating pore volumes, still inspect diffusion from low-permeability zones and sorbed inventory instead of using flushing counts as proof.'),'pore'),
U(P('吸附遲滯與殘留源','Sorption retardation and residual sources'),P('對比保守示蹤物與污染物的穿透曲線，理解水已更換而污染仍釋出的原因。','Compare conservative-tracer and contaminant breakthrough to explain persistent release after water replacement.'),'retardation'),
U(P('停泵反彈與捕獲復核','Shutdown rebound and capture review'),P('只在離線情境中暫停抽水，觀察濃度回升與水頭重建；同時確認污染是否向外擴張。','Pause pumping only in the offline scenario and observe concentration rebound and head recovery while checking outward plume migration.'),'rebound'),
U(P('長期策略與量測不確定度','Long-term strategy and uncertainty'),P('把流量與濃度的不確定度傳到移除負荷，區分真實減量、測量波動與單純稀釋。','Propagate flow and concentration uncertainty into removal load to distinguish real progress from measurement variation and dilution.'),'uncertainty')])

C('b493',P('由地下水路徑、反應時間與介質老化設計反應牆教學模型','Build a reactive-barrier teaching model from groundwater pathways, reaction time and media ageing'),'environment-remediation',['remedy','remedyguidance','sw846'],[
U(P('污染羽流與牆位概念','Plume and conceptual barrier position'),P('先在剖面定位羽流寬深、地下水流向和未污染旁通區，不能只在地表畫一條線稱完整截流。','Locate plume width and depth, groundwater direction and bypass zones in section; a surface line alone does not establish interception.'),'advection'),
U(P('被動穿流與水力匹配','Passive flow and hydraulic matching'),P('比較牆前後水頭及天然梯度，辨識污染水是穿牆、繞牆還是從牆底通過。','Compare heads across the wall and natural gradient to distinguish through-flow from side or underflow bypass.'),'gradient'),
U(P('反應介質與可用容量','Reactive medium and usable capacity'),P('用柱試驗比較介質反應、吸附及沉澱作用，保存進出水和介質固相的質量收支。','Compare reaction, sorption and precipitation in column tests and retain mass balances for influent, effluent and solids.'),'capacity'),
U(P('牆厚與接觸時間','Wall thickness and contact time'),P('從有效孔隙率而非總體積推估接觸時間，先檢驗是否有優先通道。','Estimate contact time from effective pore space and first test for preferential paths.'),'barrier_time'),
U(P('柱試驗動力學','Column-test kinetics'),P('以教學一階衰減比較不同接觸時間，量測需能區別反應和僅被介質吸附。','Use teaching first-order decay to compare contact times with measurements separating reaction from temporary sorption.'),'decay'),
U(P('反應序列與中間物','Reaction sequence and intermediates'),P('沿流向同測母物及可能中間物；母物被轉化不保證終產物已形成。','Measure parent and potential intermediates along flow; parent conversion does not prove final-product formation.'),'daughter'),
U(P('孔隙堵塞與流速變化','Pore clogging and velocity change'),P('將礦物沉澱或生物膜造成的有效孔隙變化加入教學模型，觀察流速與接觸時間一起改變。','Represent effective-pore changes from precipitation or biofilm and observe coupled velocity and residence changes.'),'advection'),
U(P('介質耗盡與負荷波動','Media exhaustion and loading variation'),P('用季節流量與濃度重新估算污染通量，分開化學容量耗盡和表面鈍化。','Re-estimate load from seasonal flow and concentration and distinguish capacity exhaustion from surface passivation.'),'capacity'),
U(P('牆內外井網驗證','Inside/outside monitoring network'),P('在上游、牆內、下游和兩側建立教學採樣格，避免只用牆內低濃度證明成功。','Build sampling cells upstream, within, downstream and beside the barrier rather than inferring success from low internal concentrations.'),'sampling'),
U(P('壽命、維護與證據交接','Life, maintenance and evidence handoff'),P('整理可用容量、實際流路及季節不確定度，向下一位玩家交付需要補測的參數。','Handoff usable capacity, actual pathways and seasonal uncertainty with a list of parameters needing further measurement.'),'uncertainty')])

C('b494',P('以電子收支、微生物反應與產物證據判讀原位生物整治','Interpret in-situ bioremediation through electron balances, biological reactions and product evidence'),'environment-remediation',['remedy','remedyguidance','brown'],[
U(P('污染路徑與可處理性','Contaminant pathway and treatability'),P('先列污染物型態、地下水路徑與電子受供體條件，確認生物可利用性及可能產物再選情境。','List contaminant forms, groundwater paths and electron donors and acceptors; assess bioavailability and products before choosing a scenario.'),'retardation'),
U(P('天然與增強生物作用','Natural and enhanced biological activity'),P('以封閉資料集比較有、無生物活性對照，避免把稀釋或揮發誤當降解。','Compare biologically active and inactive controls in a closed dataset to avoid mistaking dilution or volatilization for degradation.'),'decay'),
U(P('電子供受體收支','Electron donor/acceptor balance'),P('把污染反應和天然競爭受體分開列帳，本題只練電子當量，不提供現場投藥設定。','Account separately for target reactions and natural competing acceptors; this exercise teaches electron equivalents without field dosing.'),'electron'),
U(P('供應物輸送與反應區','Amendment delivery and reaction zone'),P('在教學含水層中比較水流速度與反應區位置，檢查供應物能否抵達受污染的低滲透部位。','Compare pore velocity and reaction-zone location in the teaching aquifer, checking access to contaminated low-permeability regions.'),'advection'),
U(P('接觸時間與水力限制','Contact time and hydraulic constraints'),P('以孔隙替換尺度討論供應物接觸，另列混合不均和短流，不能用平均時間保證每處反應。','Use pore-volume exchange to discuss contact while separately identifying incomplete mixing and bypass.'),'pore'),
U(P('微生物動力學與環境依賴','Microbial kinetics and environmental dependence'),P('同一一階常數只能描述指定資料範圍；溫度、酸鹼與受體改變時需要重新驗證反應速率。','A first-order constant describes only its fitted range; changes in temperature, pH or acceptors require rechecking the rate.'),'decay'),
U(P('串聯轉化與中間物累積','Sequential transformation and intermediate buildup'),P('將母物、中間物和終產物畫成流圖，用莫耳收支確認是否卡在某一反應階段。','Draw parent, intermediate and product flows and use molar balances to identify a stalled reaction stage.'),'daughter'),
U(P('地球化學與樣品質保','Geochemistry and sample assurance'),P('把氧化還原與產物趨勢連結，使用平行樣、空白與保存紀錄檢查採樣改變了樣本的可能性。','Relate geochemistry to product trends and use duplicates, blanks and preservation records to test sampling-induced changes.'),'duplicate'),
U(P('停止供應後的反彈','Rebound after amendment cessation'),P('在離線模型停止假想供應，檢查殘留污染是否由吸附庫存重新釋出及產物是否持續改善。','Stop hypothetical amendment in the offline model and check residual desorption and continued product improvement.'),'rebound'),
U(P('多線證據與結案判讀','Multiple lines of evidence and closure interpretation'),P('綜合污染物、產物、電子收支和水文變化，將量測不確定度帶入反應成效而非只報母物降幅。','Combine contaminants, products, electron balances and hydrology with measurement uncertainty instead of reporting parent decline alone.'),'uncertainty')])

C('b495',P('將棕地歷史、採樣品質與暴露路徑轉為可檢查的風險概念模型','Turn brownfield history, sampling quality and exposure pathways into an auditable risk model'),'environment-remediation',['brown','risk','sw846'],[
U(P('場址使用史與概念圖','Site history and conceptual diagram'),P('在虛構工業地圖標記儲槽、裝卸、排水與回填活動，先提出可被採樣推翻的污染假說。','Mark tanks, loading, drains and fill on a fictional industrial map and formulate contamination hypotheses that sampling can challenge.'),'sampling'),
U(P('污染源、途徑與受體','Source, pathway and receptor'),P('為現況工人、鄰近居民與未來用途分開畫接觸路徑，未完整路徑仍需標明被切斷的依據。','Map pathways separately for workers, neighbours and future uses, documenting evidence where a pathway is incomplete.'),'exposure_mass'),
U(P('空間異質性與採樣設計','Spatial heterogeneity and sampling design'),P('結合規則網格與設備歷史的針對性採樣，將熱點調查與區域平均估計分成不同任務。','Combine grids with historically targeted samples and separate hotspot investigation from area-mean estimation.'),'sampling'),
U(P('實驗室品質與平行樣','Laboratory assurance and duplicates'),P('查核空白、保存時間、回收率和重複性，未達量測目的的資料需保留旗標。','Check blanks, holding records, recovery and precision and flag data that do not meet the measurement objective.'),'duplicate'),
U(P('介質濃度與接觸量','Media concentration and contact quantity'),P('逐項追蹤介質單位和接觸行為，避免將 mg/kg 土壤與 mg/kg 體重混為一談。','Track media units and contact assumptions carefully and distinguish mg/kg soil from mg/kg body mass.'),'exposure_mass'),
U(P('篩選基準的適用範圍','Applicability of screening benchmarks'),P('本題使用完全假想的比較基準；在真實調查必須另核對主管機關、介質、用途與時效。','This exercise uses a wholly hypothetical benchmark; real investigations require separate checks of authority, media, land use and currency.'),'risk_index'),
U(P('地下水途徑與遷移','Groundwater pathway and migration'),P('把源區與下游受體連結，加入地下水流速、吸附和不確定流路，避免用直線距離當抵達時間。','Connect sources with downgradient receptors while accounting for velocity, sorption and uncertain paths rather than distance alone.'),'advection'),
U(P('清除、隔離與用途控制','Removal, isolation and land-use controls'),P('比較改變源濃度與切斷接觸的差異；覆蓋或用途限制必須有長期維持及失效再評估機制。','Compare reducing source concentration with interrupting contact; covers and use controls need maintenance and reassessment after failure.'),'risk_index'),
U(P('不確定度與決策敏感度','Uncertainty and decision sensitivity'),P('對流量與濃度等量測建立不確定度示例，另外列出模型結構和未採樣熱點的不確定性。','Build an uncertainty example for flow and concentration while separately listing structural and unsampled-hotspot uncertainty.'),'uncertainty'),
U(P('再利用交接與可追溯紀錄','Reuse handoff and traceable records'),P('交付概念模型、採樣座標、原始報告和控制措施的維護責任；時間資料完整率僅示範證據可追溯性。','Handoff the conceptual model, sample locations, original reports and maintenance responsibilities; temporal completeness illustrates evidence traceability only.'),'coverage')])
